INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (9, 31, 'theory', 'Quiz: security');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 31, 0, 'What reliably protects against SQL injection?', '["Manually escaping quotes in strings", "Parameterized queries: text and values are sent separately, and values are never parsed as code", "Banning apostrophes", "Disk encryption"]', 1, 'Parameters don''t work for table names, column names and sort direction: for those you need an allowlist of permitted values.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 31, 1, 'Why shouldn''t the application connect to the database as the schema owner?', '["The owner can''t read data", "It slows queries down", "The owner can drop and alter tables and bypass row-level security; the application needs least privilege", "There can be only one owner"]', 2, 'Create separate roles: the owner for migrations, the application for reading and writing, and reports read-only.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 31, 2, 'How should the passwords of application users be stored?', '["In plain text in a separate table", "With reversible encryption using a shared key", "With a fast hash without salt", "With a slow hash and a random salt: scrypt, argon2 or bcrypt"]', 3, 'The salt makes identical passwords differ, and the slow algorithm makes brute force harder.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 31, 3, 'What is row-level security (RLS) for?', '["So different users see different rows of the same table: the policy is added to the query automatically", "To encrypt backups", "To speed up connections", "To forbid indexes"]', 0, 'In multi-tenant systems the database filters out other people''s rows itself, even if the developer forgot the condition; the owner and superuser bypass policies.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (9, 31, 4, 'What does disk encryption protect against, and what should complement it?', '["Against any attack; nothing else is needed", "Against theft of drives and copies; for the network you need TLS, and to protect from the administrator, field encryption in the application", "Against injection", "Against long-running queries"]', 1, 'There is no single encryption that covers everything: understand who you are defending against, and keep keys apart from the data.');
